from __future__ import annotations
from typing import Any, Mapping, cast

from langchain_openai import ChatOpenAI

from langchain_core.messages import (
    AIMessage,
    AIMessageChunk,
    BaseMessage,
    BaseMessageChunk,
    ChatMessage,
    ChatMessageChunk,
    FunctionMessage,
    FunctionMessageChunk,
    HumanMessage,
    HumanMessageChunk,
    SystemMessage,
    SystemMessageChunk,
    ToolMessage,
    ToolMessageChunk,
)
from langchain_core.messages.tool import tool_call_chunk
from langchain_core.outputs import ChatGeneration, ChatGenerationChunk, ChatResult
from langchain_core.messages.ai import (
    UsageMetadata,
)
from langchain_openai.chat_models.base import _create_usage_metadata
import openai
from langchain_core.output_parsers.openai_tools import (
    make_invalid_tool_call,
    parse_tool_call,
)

class VllmChatOpenAI(ChatOpenAI):

    @staticmethod
    def _convert_dict_to_message(_dict: Mapping[str, Any]) -> BaseMessage:
        """Convert a dictionary to a LangChain message."""
        role = _dict.get("role")
        name = _dict.get("name")
        id_ = _dict.get("id")
        if role == "user":
            return HumanMessage(content=_dict.get("content", ""), id=id_, name=name)
        if role == "assistant":
            content = _dict.get("content", "") or ""
            additional_kwargs: dict = {}
            if (reasoning_content := _dict.get("reasoning_content")) is not None:
                additional_kwargs["reasoning_content"] = reasoning_content
            elif (reasoning := _dict.get("reasoning")) is not None:
                additional_kwargs["reasoning_content"] = reasoning
            if function_call := _dict.get("function_call"):
                additional_kwargs["function_call"] = dict(function_call)
            tool_calls = []
            invalid_tool_calls = []
            if raw_tool_calls := _dict.get("tool_calls"):
                for raw_tool_call in raw_tool_calls:
                    try:
                        tool_calls.append(parse_tool_call(raw_tool_call, return_id=True))
                    except Exception as e:
                        invalid_tool_calls.append(
                            make_invalid_tool_call(raw_tool_call, str(e))
                        )
            if audio := _dict.get("audio"):
                additional_kwargs["audio"] = audio
            return AIMessage(
                content=content,
                additional_kwargs=additional_kwargs,
                name=name,
                id=id_,
                tool_calls=tool_calls,
                invalid_tool_calls=invalid_tool_calls,
            )
        if role in ("system", "developer"):
            additional_kwargs = {"__openai_role__": role} if role == "developer" else {}
            return SystemMessage(
                content=_dict.get("content", ""),
                name=name,
                id=id_,
                additional_kwargs=additional_kwargs,
            )
        if role == "function":
            return FunctionMessage(
                content=_dict.get("content", ""), name=cast(str, _dict.get("name")), id=id_
            )
        if role == "tool":
            additional_kwargs = {}
            if "name" in _dict:
                additional_kwargs["name"] = _dict["name"]
            return ToolMessage(
                content=_dict.get("content", ""),
                tool_call_id=cast(str, _dict.get("tool_call_id")),
                additional_kwargs=additional_kwargs,
                name=name,
                id=id_,
            )
        return ChatMessage(content=_dict.get("content", ""), role=role, id=id_)

    @staticmethod
    def _convert_delta_to_message_chunk(
        _dict: Mapping[str, Any], default_class: type[BaseMessageChunk]
    ) -> BaseMessageChunk:
        """Convert to a LangChain message chunk."""
        id_ = _dict.get("id")
        role = cast(str, _dict.get("role"))
        content = cast(str, _dict.get("content") or "")
        additional_kwargs: dict = {}

        # Debug print to verify this function is being called
        if (reasoning_content := _dict.get("reasoning_content")) is not None:
            additional_kwargs["reasoning_content"] = reasoning_content
        elif (reasoning := _dict.get("reasoning")) is not None:
            additional_kwargs["reasoning_content"] = reasoning
        if _dict.get("function_call"):
            function_call = dict(_dict["function_call"])
            if "name" in function_call and function_call["name"] is None:
                function_call["name"] = ""
            additional_kwargs["function_call"] = function_call
        tool_call_chunks = []
        if raw_tool_calls := _dict.get("tool_calls"):
            try:
                tool_call_chunks = [
                    tool_call_chunk(
                        name=rtc["function"].get("name"),
                        args=rtc["function"].get("arguments"),
                        id=rtc.get("id"),
                        index=rtc["index"],
                    )
                    for rtc in raw_tool_calls
                ]
            except KeyError:
                pass

        if role == "user" or default_class == HumanMessageChunk:
            return HumanMessageChunk(content=content, id=id_)
        if role == "assistant" or default_class == AIMessageChunk:
            return AIMessageChunk(
                content=content,
                additional_kwargs=additional_kwargs,
                id=id_,
                tool_call_chunks=tool_call_chunks,
            )
        if role in ("system", "developer") or default_class == SystemMessageChunk:
            if role == "developer":
                additional_kwargs = {"__openai_role__": "developer"}
            else:
                additional_kwargs = {}
            return SystemMessageChunk(
                content=content, id=id_, additional_kwargs=additional_kwargs
            )
        if role == "function" or default_class == FunctionMessageChunk:
            return FunctionMessageChunk(content=content, name=_dict["name"], id=id_)
        if role == "tool" or default_class == ToolMessageChunk:
            return ToolMessageChunk(
                content=content, tool_call_id=_dict["tool_call_id"], id=id_
            )
        if role or default_class == ChatMessageChunk:
            return ChatMessageChunk(content=content, role=role, id=id_)
        return default_class(content=content, id=id_)

    def _create_chat_result(
        self,
        response: dict | openai.BaseModel,
        generation_info: dict | None = None,
    ) -> ChatResult:
        generations = []

        response_dict = (
            response if isinstance(response, dict) else response.model_dump()
        )
        # Sometimes the AI Model calling will get error, we should raise it (this is
        # typically followed by a null value for `choices`, which we raise for
        # separately below).
        if response_dict.get("error"):
            raise ValueError(response_dict.get("error"))

        # Raise informative error messages for non-OpenAI chat completions APIs
        # that return malformed responses.
        try:
            choices = response_dict["choices"]
        except KeyError as e:
            msg = f"Response missing `choices` key: {response_dict.keys()}"
            raise KeyError(msg) from e

        if choices is None:
            msg = "Received response with null value for `choices`."
            raise TypeError(msg)

        token_usage = response_dict.get("usage")
        service_tier = response_dict.get("service_tier")

        for res in choices:
            message = self._convert_dict_to_message(res["message"])
            if token_usage and isinstance(message, AIMessage):
                message.usage_metadata = _create_usage_metadata(
                    token_usage, service_tier
                )
            generation_info = generation_info or {}
            generation_info["finish_reason"] = (
                res.get("finish_reason")
                if res.get("finish_reason") is not None
                else generation_info.get("finish_reason")
            )
            if "logprobs" in res:
                generation_info["logprobs"] = res["logprobs"]
            gen = ChatGeneration(message=message, generation_info=generation_info)
            generations.append(gen)
        llm_output = {
            "token_usage": token_usage,
            "model_provider": "openai",
            "model_name": response_dict.get("model", self.model_name),
            "system_fingerprint": response_dict.get("system_fingerprint", ""),
        }
        if "id" in response_dict:
            llm_output["id"] = response_dict["id"]
        if service_tier:
            llm_output["service_tier"] = service_tier

        if isinstance(response, openai.BaseModel) and getattr(
            response, "choices", None
        ):
            message = response.choices[0].message  # type: ignore[attr-defined]
            if hasattr(message, "parsed"):
                generations[0].message.additional_kwargs["parsed"] = message.parsed
            if hasattr(message, "refusal"):
                generations[0].message.additional_kwargs["refusal"] = message.refusal

        return ChatResult(generations=generations, llm_output=llm_output)

    def _convert_chunk_to_generation_chunk(
        self,
        chunk: dict,
        default_chunk_class: type,
        base_generation_info: dict | None,
    ) -> ChatGenerationChunk | None:
        if chunk.get("type") == "content.delta":  # From beta.chat.completions.stream
            return None
        token_usage = chunk.get("usage")
        choices = (
            chunk.get("choices", [])
            # From beta.chat.completions.stream
            or chunk.get("chunk", {}).get("choices", [])
        )

        usage_metadata: UsageMetadata | None = (
            _create_usage_metadata(token_usage, chunk.get("service_tier"))
            if token_usage
            else None
        )
        if len(choices) == 0:
            # logprobs is implicitly None
            generation_chunk = ChatGenerationChunk(
                message=default_chunk_class(content="", usage_metadata=usage_metadata),
                generation_info=base_generation_info,
            )
            if self.output_version == "v1":
                generation_chunk.message.content = []
                generation_chunk.message.response_metadata["output_version"] = "v1"

            return generation_chunk

        choice = choices[0]
        if choice["delta"] is None:
            return None

        message_chunk = self._convert_delta_to_message_chunk(
            choice["delta"], default_chunk_class
        )
        generation_info = {**base_generation_info} if base_generation_info else {}

        if finish_reason := choice.get("finish_reason"):
            generation_info["finish_reason"] = finish_reason
            if model_name := chunk.get("model"):
                generation_info["model_name"] = model_name
            if system_fingerprint := chunk.get("system_fingerprint"):
                generation_info["system_fingerprint"] = system_fingerprint
            if service_tier := chunk.get("service_tier"):
                generation_info["service_tier"] = service_tier
            if isinstance(message_chunk, AIMessageChunk):
                message_chunk.chunk_position = "last"

        logprobs = choice.get("logprobs")
        if logprobs:
            generation_info["logprobs"] = logprobs

        if usage_metadata and isinstance(message_chunk, AIMessageChunk):
            message_chunk.usage_metadata = usage_metadata

        message_chunk.response_metadata["model_provider"] = "openai"
        return ChatGenerationChunk(
            message=message_chunk, generation_info=generation_info or None
        )


